"""Mock model oracle used by the Sivand benchmark."""

from __future__ import annotations

from collections import OrderedDict
from dataclasses import dataclass
import hashlib
from typing import Callable, Iterable

from reduction.property_test import PropertyTester
from reduction.token import Token, Tokenizer


SECURITY_KEYWORDS = frozenset(
    {
        "eval",
        "exec",
        "os",
        "pickle",
        "popen",
        "shell",
        "subprocess",
        "system",
    }
)


@dataclass(frozen=True)
class ModelPrediction:
    """Prediction payload returned by the deterministic mock model."""

    label: str
    confidence: float
    logits: dict[str, float]
    attention_weights: list[float]


class PredictionCache:
    """Content-hash cache with a simple LRU eviction policy."""

    def __init__(self, max_size: int = 256):
        self.max_size = max(1, max_size)
        self._entries: OrderedDict[str, ModelPrediction] = OrderedDict()

    def get(self, source: str) -> ModelPrediction | None:
        key = self._key(source)
        cached = self._entries.get(key)
        if cached is None:
            return None
        self._entries.move_to_end(key)
        return cached

    def put(self, source: str, prediction: ModelPrediction) -> None:
        key = self._key(source)
        self._entries[key] = prediction
        self._entries.move_to_end(key)
        while len(self._entries) > self.max_size:
            self._entries.popitem(last=False)

    def get_or_set(
        self,
        source: str,
        factory: Callable[[str], ModelPrediction],
    ) -> ModelPrediction:
        cached = self.get(source)
        if cached is not None:
            return cached
        prediction = factory(source)
        self.put(source, prediction)
        return prediction

    def clear(self) -> None:
        self._entries.clear()

    def _key(self, source: str) -> str:
        return hashlib.sha256(source.encode("utf-8")).hexdigest()


class MockModel:
    """Keyword-driven stand-in for a neural vulnerability classifier."""

    def __init__(self):
        self.tokenizer = Tokenizer()

    def predict(self, source: str) -> ModelPrediction:
        tokens = self._tokens(source)
        security_hits = sum(
            1
            for token in tokens
            if token.value.lower() in SECURITY_KEYWORDS
        )
        keyword_hits = sum(1 for token in tokens if token.type == "KEYWORD")

        vulnerable_score = 0.35 + (0.65 * security_hits) + (0.04 * keyword_hits)
        benign_score = 0.8 + (0.01 * len(tokens)) - (0.25 * security_hits)

        label = "vulnerable" if security_hits or vulnerable_score >= benign_score else "benign"
        if label == "vulnerable":
            vulnerable_score += 0.25
        else:
            benign_score += 0.25

        total_score = max(vulnerable_score + benign_score, 1e-9)
        margin = abs(vulnerable_score - benign_score)
        confidence = min(0.999, 0.5 + (margin / (2.0 * total_score)))

        logits = {
            "benign": benign_score,
            "vulnerable": vulnerable_score,
        }
        attention_weights = [self._attention_weight(token) for token in tokens]

        return ModelPrediction(
            label=label,
            confidence=confidence,
            logits=logits,
            attention_weights=attention_weights,
        )

    def batch_predict(self, sources: Iterable[str]) -> list[ModelPrediction]:
        return [self.predict(source) for source in sources]

    def get_feature_importance(self, source: str) -> list[tuple[str, float]]:
        prediction = self.predict(source)
        return sorted(
            [
                (token.value, weight)
                for token, weight in zip(self._tokens(source), prediction.attention_weights)
            ],
            key=lambda item: (-item[1], item[0]),
        )

    def _tokens(self, source: str) -> list[Token]:
        return [
            token
            for token in self.tokenizer.tokenize(source)
            if token.type != "NEWLINE"
        ]

    def _attention_weight(self, token: Token) -> float:
        value = token.value.lower()
        if value in SECURITY_KEYWORDS:
            return 1.0
        if token.type == "KEYWORD":
            return 0.8
        if token.type == "IDENTIFIER":
            return 0.55
        if token.type in {"STRING", "FSTRING"}:
            return 0.45
        if token.type == "NUMBER":
            return 0.35
        if token.type == "OPERATOR":
            return 0.25
        if token.type == "DELIMITER":
            return 0.15
        return 0.1


class ModelOracle(PropertyTester):
    """Property tester that preserves a target mock-model prediction."""

    def __init__(
        self,
        model: MockModel,
        target_label: str,
        cache_size: int = 256,
    ):
        self.model = model
        self.target_label = target_label
        self.cache = PredictionCache(cache_size)
        self.test_script = "<model-oracle>"
        self.work_dir = ""
        self.timeout = 0
        self._test_count = 0
        self._oracle_calls = 0

    @property
    def oracle_calls(self) -> int:
        return self._oracle_calls

    def predict(self, program_source: str) -> ModelPrediction:
        cached = self.cache.get(program_source)
        if cached is not None:
            return cached

        prediction = self.model.predict(program_source)
        self._oracle_calls += 1
        self.cache.put(program_source, prediction)
        return prediction

    def batch_predict(self, sources: Iterable[str]) -> list[ModelPrediction]:
        return [self.predict(source) for source in sources]

    def get_feature_importance(self, source: str) -> list[tuple[str, float]]:
        prediction = self.predict(source)
        tokens = [
            token.value
            for token in self.model.tokenizer.tokenize(source)
            if token.type != "NEWLINE"
        ]
        return sorted(
            zip(tokens, prediction.attention_weights),
            key=lambda item: (-item[1], item[0]),
        )

    def test(self, program_source: str) -> bool:
        self._test_count += 1
        return self.predict(program_source).label == self.target_label

    def reset_count(self) -> None:
        self._test_count = 0
        self._oracle_calls = 0
        self.cache.clear()

