"""Perses-style reduction and attribution helpers for Sivand."""

from __future__ import annotations

from dataclasses import dataclass

from reduction.grammar import Grammar
from reduction.perses_reducer import PersesReducer, QUANTIFIED_NODE_TYPES
from reduction.property_test import PropertyTester
from reduction.sivand.attention_priority import AttentionExtractor, AttentionPriorityQueue
from reduction.sivand.model_oracle import ModelOracle, ModelPrediction
from reduction.token import Token, Tokenizer
from reduction.tree import NodeType, SparTreeNode


@dataclass(frozen=True)
class SaliencyEntry:
    """Importance assignment for one original token."""

    index: int
    token: str
    score: float
    essential: bool


@dataclass
class SaliencyMap:
    """Token-level explanation for the original source program."""

    target_label: str
    entries: list[SaliencyEntry]

    def to_dict(self) -> dict[str, float]:
        return {
            f"{entry.index}:{entry.token}": entry.score
            for entry in self.entries
        }

    @property
    def essential_count(self) -> int:
        return sum(1 for entry in self.entries if entry.essential)

    @property
    def sparsity(self) -> float:
        if not self.entries:
            return 1.0
        return 1.0 - (self.essential_count / len(self.entries))


@dataclass
class MinimalExplanation:
    """Container for a full Sivand explanation result."""

    original_source: str
    minimal_source: str
    prediction: ModelPrediction
    original_tokens: int
    minimal_tokens: int
    oracle_calls: int
    saliency_map: SaliencyMap
    feature_ranking: list[SaliencyEntry]

    @property
    def essential_count(self) -> int:
        return self.saliency_map.essential_count

    @property
    def sparsity(self) -> float:
        return self.saliency_map.sparsity

    @property
    def reduction_stats(self) -> dict[str, float | int]:
        return {
            "original_tokens": self.original_tokens,
            "minimal_tokens": self.minimal_tokens,
            "oracle_calls": self.oracle_calls,
            "reduction_ratio": self.reduction_ratio,
        }

    @property
    def reduction_ratio(self) -> float:
        if self.original_tokens == 0:
            return 0.0
        return 1.0 - (self.minimal_tokens / self.original_tokens)


class IterativeAttributor:
    """Assign token importance by checking prediction stability under deletion."""

    def __init__(self, oracle: ModelOracle):
        self.oracle = oracle
        self.tokenizer = Tokenizer()

    def attribute(
        self,
        source: str,
        target_label: str | None = None,
    ) -> SaliencyMap:
        target = target_label or self.oracle.target_label
        base_prediction = self.oracle.predict(source)
        tokens = [
            token
            for token in self.tokenizer.tokenize(source)
            if token.type != "NEWLINE"
        ]
        entries: list[SaliencyEntry] = []

        for index, token in enumerate(tokens):
            candidate_source = render_tokens(
                [item for offset, item in enumerate(tokens) if offset != index]
            )
            survives = self.oracle.test(candidate_source)
            candidate_prediction = self.oracle.predict(candidate_source)
            essential = not survives

            if essential:
                attention = (
                    base_prediction.attention_weights[index]
                    if index < len(base_prediction.attention_weights)
                    else 0.0
                )
                score = 1.0 + attention
            else:
                score = max(0.0, base_prediction.confidence - candidate_prediction.confidence)

            entries.append(
                SaliencyEntry(
                    index=index,
                    token=token.value,
                    score=score,
                    essential=essential,
                )
            )

        return SaliencyMap(target_label=target, entries=entries)


class SivandReducer(PersesReducer):
    """Perses-style reducer with optional attention-guided prioritization."""

    def __init__(
        self,
        grammar: Grammar,
        predictor: ModelOracle,
        use_attention_priority: bool = True,
    ):
        super().__init__(grammar)
        self.predictor = predictor
        self.use_attention_priority = use_attention_priority
        self.attention_extractor = AttentionExtractor(predictor)

    @property
    def name(self) -> str:
        return "sivand"

    def _reduce_once(
        self,
        tree: SparTreeNode,
        tester: PropertyTester,
    ) -> SparTreeNode:
        if not self.use_attention_priority:
            return super()._reduce_once(tree, tester)

        _, attention_by_path = self.attention_extractor.extract(tree, tree.to_source())
        queue = AttentionPriorityQueue.from_tree(tree, attention_by_path)

        while queue:
            entry = queue.pop()
            node = self._node_at_path(tree, entry.path)
            if node is None or node.token_count() == 0:
                continue

            if entry.path and node.node_type in (NodeType.OPTIONAL, NodeType.KLEENE_STAR):
                candidate = self._try_delete_quantified_node(tree, entry, tester)
                if candidate is not None:
                    return candidate

            if node.node_type in QUANTIFIED_NODE_TYPES:
                candidate = self._ddmin_quantified_children(tree, entry.path, tester)
                if candidate is not None:
                    return candidate

            if node.node_type == NodeType.REGULAR:
                candidate = self._replace_with_descendant(tree, entry.path, tester)
                if candidate is not None:
                    return candidate

        return tree


def render_tokens(tokens: list[Token]) -> str:
    """Reconstruct source from a token sequence after token-level edits."""
    if not tokens:
        return ""

    grouped: dict[int, list[Token]] = {}
    for token in tokens:
        grouped.setdefault(token.line, []).append(token)

    lines: list[str] = []
    for line_number in sorted(grouped):
        line_tokens = sorted(grouped[line_number], key=lambda item: item.col)
        current_col = 0
        line = ""
        for token in line_tokens:
            if token.type == "INDENT":
                if current_col == 0:
                    line += token.value
                    current_col = len(token.value)
                continue
            if token.col > current_col:
                line += " " * (token.col - current_col)
            elif current_col > 0 and line and not line.endswith(" "):
                line += " "
            line += token.value
            current_col = token.col + len(token.value)
        lines.append(line.rstrip())

    return "\n".join(lines) + ("\n" if lines else "")

