"""Attention-guided traversal helpers for the Sivand reducer."""

from __future__ import annotations

import heapq
from itertools import count

from reduction.sivand.model_oracle import MockModel, ModelOracle, ModelPrediction
from reduction.tree import NodeType, SparTreeNode
from reduction.tree_utils import TreePathEntry, walk_entries


class AttentionExtractor:
    """Compute node-level attention scores from token attention weights."""

    def __init__(self, predictor: MockModel | ModelOracle):
        self.predictor = predictor

    def extract(
        self,
        tree: SparTreeNode,
        source: str | None = None,
    ) -> tuple[ModelPrediction, dict[tuple[int, ...], float]]:
        source = source or tree.to_source()
        prediction = self.predictor.predict(source)

        token_scores = {
            id(token): prediction.attention_weights[index]
            if index < len(prediction.attention_weights)
            else 0.0
            for index, token in enumerate(tree.tokens())
        }

        attention_by_path: dict[tuple[int, ...], float] = {}
        for entry in walk_entries(tree):
            scores = [
                token_scores.get(id(token), 0.0)
                for token in entry.node.tokens()
            ]
            attention_by_path[entry.path] = (
                sum(scores) / len(scores)
                if scores
                else 0.0
            )

        return prediction, attention_by_path


class AttentionPriorityQueue:
    """Priority queue that favors low-attention nodes first."""

    def __init__(self):
        self._heap: list[tuple[float, int, int, int, TreePathEntry]] = []
        self._serial = count()

    @classmethod
    def from_tree(
        cls,
        tree: SparTreeNode,
        attention_by_path: dict[tuple[int, ...], float],
    ) -> "AttentionPriorityQueue":
        queue = cls()
        for entry in walk_entries(tree):
            if entry.node.node_type == NodeType.TOKEN:
                continue
            if entry.node.token_count() == 0:
                continue
            queue.push(entry, attention_by_path.get(entry.path, 0.0))
        return queue

    def push(self, entry: TreePathEntry, attention: float) -> None:
        heapq.heappush(
            self._heap,
            (
                attention,
                -entry.node.token_count(),
                len(entry.path),
                next(self._serial),
                entry,
            ),
        )

    def pop(self) -> TreePathEntry:
        return heapq.heappop(self._heap)[-1]

    def __bool__(self) -> bool:
        return bool(self._heap)

    def __len__(self) -> int:
        return len(self._heap)
